import * as React from "react";
import { Plus, X } from "lucide-react";
import { cn } from "@/lib/utils";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";

/**
 * Token multi-select — chips with a remove ×, plus an "+ Add …" affordance that
 * opens a searchable list with a check on the chosen options.
 *
 * This is the DS's `form-layout/MultiSelect` (Figma "Dropdown … Add Margins",
 * 27593:15012) — markup, sizes and classes copied verbatim so the two cannot
 * drift. The only change is the API: the DS version hardcodes its option list
 * and label and keeps selection in private state, so it can't be pointed at
 * anything. This one takes `options`, `value`, `onChange` and `addLabel`.
 *
 * DS FOLLOW-UP: generalise `MultiSelect` to take those four props and delete
 * this file. It is a copy only because the DS component cannot currently be
 * reused, not because this screen needs anything different.
 */

/** Small circular initial badge used as a token / item leading glyph. */
function InitialBadge({ label }: { label: string }) {
  return (
    <span className="flex size-4 items-center justify-center rounded-full bg-accent text-[9px] font-semibold uppercase">
      {label[0]}
    </span>
  );
}

export interface TokenMultiSelectProps {
  options: string[];
  value: string[];
  onChange: (next: string[]) => void;
  /** Trailing affordance, e.g. "Add tags". */
  addLabel: string;
  /** Search field placeholder, e.g. "Search tags...". */
  searchPlaceholder: string;
  /** Sits edge to edge inside a card: no border, no radius, no inset of its
   *  own — the card's edge is its edge. */
  flush?: boolean;
  /** Chips drawn with a blue outline — e.g. the products marked winter blend. */
  highlighted?: string[];
  /** A small word shown inside a highlighted chip, e.g. "Winter blend". */
  highlightLabel?: string;
  /** When set, clicking a chip calls this instead of opening the list. */
  onChipClick?: (opt: string) => void;
  /**
   * Bump it and every chip blinks a blue outline ONCE — "these are clickable
   * now". 0 never blinks.
   */
  flashKey?: number;
}

export function TokenMultiSelect({
  options,
  value,
  onChange,
  addLabel,
  searchPlaceholder,
  flush,
  highlighted,
  highlightLabel,
  onChipClick,
  flashKey = 0,
}: TokenMultiSelectProps) {
  const [open, setOpen] = React.useState(false);
  const [flashing, setFlashing] = React.useState(false);
  React.useEffect(() => {
    if (!flashKey) return;
    setFlashing(true);
    const t = window.setTimeout(() => setFlashing(false), 650);
    return () => window.clearTimeout(t);
  }, [flashKey]);

  const toggle = (opt: string) =>
    onChange(
      value.includes(opt) ? value.filter((o) => o !== opt) : [...value, opt]
    );

  const remove = (opt: string) => onChange(value.filter((o) => o !== opt));

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <button
          type="button"
          className={cn(
            "flex min-h-11 w-full flex-wrap items-center gap-2 rounded-md border border-input bg-transparent px-2 py-2 text-left outline-none transition-colors",
            "hover:border-fp-outline-2 focus-visible:ring-2 focus-visible:ring-ring/50",
            "data-[state=open]:border-ring",
            /* FLUSH IS THE BOX, NOT THE CONTENT. The unit meets the card's
               edges, but the chips inside keep the card's 16px inset — a chip
               touching the edge reads as cut off. (Pavan, 2026-09-25.) */
            flush && "rounded-none border-0 px-4 py-2 hover:bg-fp-surface-1a focus-visible:ring-inset",
            value.length === 0 && "justify-center"
          )}
        >
          {value.map((opt) => (
            <span
              key={opt}
              role={onChipClick ? "button" : undefined}
              aria-pressed={onChipClick ? Boolean(highlighted?.includes(opt)) : undefined}
              onClick={
                onChipClick
                  ? (e) => {
                      e.stopPropagation();
                      e.preventDefault();
                      onChipClick(opt);
                    }
                  : undefined
              }
              className={cn(
                "inline-flex items-center gap-1.5 rounded-md border border-border bg-fp-surface-1b py-1 pr-1 pl-1.5 text-sm",
                onChipClick && "cursor-pointer hover:border-fp-outline-2",
                highlighted?.includes(opt) &&
                  "border-fp-banner-accent-info hover:border-fp-banner-accent-info",
                flashing && "fp-attention-info"
              )}
            >
              <InitialBadge label={opt} />
              {opt}
              {highlightLabel && highlighted?.includes(opt) && (
                <span className="rounded-sm bg-fp-banner-accent-info/10 px-1 text-xs text-fp-banner-accent-info">
                  {highlightLabel}
                </span>
              )}
              <span
                role="button"
                tabIndex={-1}
                aria-label={`Remove ${opt}`}
                onClick={(e) => {
                  e.stopPropagation();
                  remove(opt);
                }}
                className="flex size-4 items-center justify-center rounded-sm text-muted-foreground hover:text-foreground"
              >
                <X className="size-3.5" />
              </span>
            </span>
          ))}
          <span className="inline-flex items-center gap-1 text-sm text-muted-foreground">
            <Plus className="size-4" />
            {addLabel}
          </span>
        </button>
      </PopoverTrigger>
      <PopoverContent
        align="start"
        className="w-(--radix-popover-trigger-width) p-0"
      >
        <Command>
          <CommandInput placeholder={searchPlaceholder} />
          <CommandList>
            <CommandEmpty>No options found.</CommandEmpty>
            <CommandGroup>
              {options.map((opt) => (
                <CommandItem
                  key={opt}
                  value={opt}
                  icon={<InitialBadge label={opt} />}
                  selected={value.includes(opt)}
                  // keep the menu open for multi-select; cmdk doesn't close it
                  onSelect={() => toggle(opt)}
                >
                  {opt}
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

import * as React from "react";
import { Command as CommandPrimitive } from "cmdk";
import { SearchIcon, CheckIcon } from "lucide-react";

import { cn } from "@/lib/utils";

function Command({
  className,
  ...props
}: React.ComponentProps<typeof CommandPrimitive>) {
  return (
    <CommandPrimitive
      data-slot="command"
      className={cn(
        "flex h-full w-full flex-col overflow-hidden rounded-md bg-popover text-popover-foreground",
        className
      )}
      {...props}
    />
  );
}

function CommandInput({
  className,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Input>) {
  return (
    <div
      data-slot="command-input-wrapper"
      className="flex h-9 items-center gap-2 border-b border-border px-3"
    >
      <SearchIcon className="size-4 shrink-0 opacity-50" />
      <CommandPrimitive.Input
        data-slot="command-input"
        className={cn(
          "flex h-10 w-full rounded-md bg-transparent py-3 text-sm outline-hidden placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50",
          className
        )}
        {...props}
      />
    </div>
  );
}

function CommandList({
  className,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.List>) {
  return (
    <CommandPrimitive.List
      data-slot="command-list"
      className={cn(
        "max-h-[300px] scroll-py-1 overflow-x-hidden overflow-y-auto",
        className
      )}
      {...props}
    />
  );
}

function CommandEmpty({
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Empty>) {
  return (
    <CommandPrimitive.Empty
      data-slot="command-empty"
      className="py-6 text-center text-sm"
      {...props}
    />
  );
}

function CommandGroup({
  className,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Group>) {
  return (
    <CommandPrimitive.Group
      data-slot="command-group"
      className={cn(
        "overflow-hidden p-1 text-foreground [&_[cmdk-group-heading]]:px-2 [&_[cmdk-group-heading]]:py-1.5 [&_[cmdk-group-heading]]:text-xs [&_[cmdk-group-heading]]:font-medium [&_[cmdk-group-heading]]:text-muted-foreground",
        className
      )}
      {...props}
    />
  );
}

function CommandSeparator({
  className,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Separator>) {
  return (
    <CommandPrimitive.Separator
      data-slot="command-separator"
      className={cn("-mx-1 h-px bg-border", className)}
      {...props}
    />
  );
}

/**
 * Command item — Figma "Command / Item" (430:20061). Beyond the raw cmdk item,
 * this surfaces the component's documented properties as ergonomic props:
 *   - `icon`        → leading slot (the "Icon" variant; an INSTANCE_SWAP in Figma)
 *   - `selected`    → trailing ✓ (the "Selected" variant)
 *   - `shortcut`    → trailing shortcut text (the "Shortcut Text" property)
 *   - `showShortcut`→ toggles the shortcut (the "Show Shortcut" BOOLEAN, default true)
 * The Default/Hover/Disabled "State" variant is left to cmdk (it drives
 * `data-[selected]`/`data-[disabled]`), so it isn't a manual prop. Passing only
 * `children` keeps the plain shadcn behaviour — every existing call still works.
 *
 * ⚠️ DO NOT hand-roll this row layout. Setting ANY of `icon` / `selected` /
 * `shortcut` switches the item into structured mode, which wraps `children` in a
 * single `flex-1 truncate` span. Flex children you pass inside `children` then
 * collapse onto one truncated line, silently — no error, just a broken row that
 * costs real debugging time. Use the slots:
 *
 * ```tsx
 * <CommandItem icon={<Truck />} shortcut="12 orders">Carrier name</CommandItem>
 * ```
 *
 * `selected` renders a trailing ✓, which marks *the* chosen row — correct for
 * SINGLE-select. For multi-select use `MultiSelectList` (checkbox rows): a ✓ on
 * a multi-select list reads as "this is the current value", and with nothing yet
 * chosen the list is indistinguishable from a single-select one.
 */
function CommandItem({
  className,
  children,
  icon,
  selected,
  shortcut,
  showShortcut = true,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Item> & {
  icon?: React.ReactNode;
  selected?: boolean;
  shortcut?: React.ReactNode;
  showShortcut?: boolean;
}) {
  // Only compose the structured layout when an FP prop is supplied; otherwise
  // render children verbatim (backward-compatible with bare cmdk usage).
  const structured = icon != null || selected != null || shortcut != null;
  return (
    <CommandPrimitive.Item
      data-slot="command-item"
      className={cn(
        "relative flex cursor-default items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-hidden select-none data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50 data-[selected=true]:bg-accent data-[selected=true]:text-accent-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 [&_svg:not([class*='text-'])]:text-muted-foreground",
        className
      )}
      {...props}
    >
      {structured ? (
        <>
          {icon}
          <span className="flex-1 truncate">{children}</span>
          {selected && <CheckIcon className="ml-auto size-4 text-foreground" />}
          {shortcut != null && showShortcut && (
            <CommandShortcut>{shortcut}</CommandShortcut>
          )}
        </>
      ) : (
        children
      )}
    </CommandPrimitive.Item>
  );
}

/**
 * Right-aligned meta slot in a `CommandItem`.
 *
 * `variant` exists because this slot has two jobs. `keycap` is the wide-tracked
 * treatment that suits `⌘K`; `meta` is plain, for the counts, dates and hints
 * that are just as natural on the right of a row and that wide tracking makes
 * look broken. `meta` is the default — wide tracking is the special case, so it
 * should be the one you opt into.
 */
function CommandShortcut({
  className,
  variant = "meta",
  ...props
}: React.ComponentProps<"span"> & { variant?: "meta" | "keycap" }) {
  return (
    <span
      data-slot="command-shortcut"
      data-variant={variant}
      className={cn(
        "ml-auto text-xs text-muted-foreground",
        variant === "keycap" && "tracking-widest",
        className
      )}
      {...props}
    />
  );
}

export {
  Command,
  CommandInput,
  CommandList,
  CommandEmpty,
  CommandGroup,
  CommandItem,
  CommandShortcut,
  CommandSeparator,
};

"use client"

import * as React from "react"
import { Popover as PopoverPrimitive } from "radix-ui"

import { cn } from "@/lib/utils"

function Popover({
  ...props
}: React.ComponentProps<typeof PopoverPrimitive.Root>) {
  return <PopoverPrimitive.Root data-slot="popover" {...props} />
}

function PopoverTrigger({
  ...props
}: React.ComponentProps<typeof PopoverPrimitive.Trigger>) {
  return <PopoverPrimitive.Trigger data-slot="popover-trigger" {...props} />
}

function PopoverContent({
  className,
  align = "center",
  sideOffset = 4,
  ...props
}: React.ComponentProps<typeof PopoverPrimitive.Content>) {
  return (
    <PopoverPrimitive.Portal>
      <PopoverPrimitive.Content
        data-slot="popover-content"
        align={align}
        sideOffset={sideOffset}
        className={cn(
          "z-50 w-72 origin-(--radix-popover-content-transform-origin) rounded-md border bg-popover p-4 text-popover-foreground shadow-md outline-hidden data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95",
          className
        )}
        {...props}
      />
    </PopoverPrimitive.Portal>
  )
}

function PopoverAnchor({
  ...props
}: React.ComponentProps<typeof PopoverPrimitive.Anchor>) {
  return <PopoverPrimitive.Anchor data-slot="popover-anchor" {...props} />
}

function PopoverHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="popover-header"
      className={cn("flex flex-col gap-1 text-sm", className)}
      {...props}
    />
  )
}

function PopoverTitle({ className, ...props }: React.ComponentProps<"h2">) {
  return (
    <div
      data-slot="popover-title"
      className={cn("font-medium", className)}
      {...props}
    />
  )
}

function PopoverDescription({
  className,
  ...props
}: React.ComponentProps<"p">) {
  return (
    <p
      data-slot="popover-description"
      className={cn("text-muted-foreground", className)}
      {...props}
    />
  )
}

export {
  Popover,
  PopoverTrigger,
  PopoverContent,
  PopoverAnchor,
  PopoverHeader,
  PopoverTitle,
  PopoverDescription,
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/** Merge conditional class names and de-dupe Tailwind utilities. */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
